android.extraProguardRules:
# --- Hermes / JNI: nomlar JNI orqali qidiriladi, o'zgartirilmasin ---
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.soloader.** { *; }

# --- React Native ko'prigi va codegen (New Architecture) ---
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.react.uimanager.** { *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keep @com.facebook.proguard.annotations.DoNotStrip class *

# --- Expo modullari: modul ta'riflari Kotlin reflection bilan o'qiladi ---
-keep class expo.modules.** { *; }
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keepclassmembers class * extends expo.modules.kotlin.modules.Module { *; }

# --- Kotlin metadata: reflection'ga kerak ---
-keep class kotlin.Metadata { *; }
-keepattributes *Annotation*, Signature, InnerClasses, EnclosingMethod

# --- Crash izlari o'qilishi uchun qator raqamlari saqlanadi ---
-keepattributes SourceFile, LineNumberTable
-renamesourcefileattribute SourceFile
